  async function api(path,options){const headers={accept:'application/json',...(options?.headers||{})},session=localStorage.getItem(sessionKey),authPath=/^\/auth\/qr\//.test(path)||path==='/auth/logout',base=authPath?neteaseAuthApiBase:neteaseApiBase;if(session&&(path==='/auth/logout'||!authPath))headers.authorization=`Bearer ${session}`;const request=window.IdealMachineFetch||window.fetch.bind(window);const response=await request(`${base}${path}`,{...options,idealScope:'music',credentials:'omit',cache:'no-store',headers});let data=null;try{data=await response.json();}catch{}if(!response.ok)throw new Error(data?.error||`API ${response.status}`);return data;}
