  function changeTrack(step){const queue=playbackQueue(),song=current(),index=queue.findIndex(item=>String(item.id)===String(song?.id));if(!queue.length||index<0)return window.alert('当前没有可切换的歌曲。');const candidates=queue.filter(item=>String(item.id)!==String(song?.id));const next=playMode==='shuffle'&&candidates.length?candidates[Math.floor(Math.random()*candidates.length)]:queue[(index+step+queue.length)%queue.length];activate(next,{preserveScroll:true});}
