  async function restoreCurrent(){let song=current();if(!song)return;let knownUrl=song.playUrl||song.preview||song.url||'';if(!knownUrl&&song.title){let match=null;const term=`${song.title} ${song.artist||''}`;if(song.source==='netease'){try{knownUrl=await neteasePlayUrl(song.id);if(!knownUrl)knownUrl=neteaseOuterUrl(song.id);}catch{}}else if(song.source==='character'||(!song.source&&song.musicTitle)){try{const matches=await searchNetease(term);match=matches.find(item=>item.title===song.title)||matches[0];if(match)knownUrl=await neteasePlayUrl(match.id);if(!knownUrl&&match)knownUrl=neteaseOuterUrl(match.id);}catch{}}else if(song.source==='deezer'){try{match=(await searchDeezer(term))[0];knownUrl=match?.playUrl||'';}catch{}}else if(song.source==='itunes'){try{match=(await searchItunes(term))[0];knownUrl=match?.playUrl||'';}catch{}}if(!knownUrl&&song.source!=='netease'){const fallbacks=[searchDeezer,searchItunes,searchAudius];for(const search of fallbacks){try{const found=await search(term),candidate=found.find(item=>item.playUrl)||found[0];if(candidate?.playUrl){match=candidate;knownUrl=candidate.playUrl;break;}}catch{}}}if(match&&knownUrl){song={...song,...match,playUrl:knownUrl,isPreview:Boolean(match.isPreview||['deezer','itunes'].includes(match.source))};state.current[state.profileId]=song;save();}}if(!knownUrl&&song.source!=='file')return window.alert('这首音乐没有可用播放地址，可能需要登录音乐平台或该歌曲暂不提供试听。');if(audio.src&&knownUrl&&audio.src===knownUrl)return;try{if(song.source==='file'){const blob=await getFile(song.id);if(blob){const playUrl=URL.createObjectURL(blob);if(audio.src&&audio.src===song.playUrl)return;state.current[state.profileId]={...song,playUrl};audio.src=playUrl;save();}}else if(knownUrl){state.current[state.profileId]={...song,playUrl:knownUrl};save();audio.src=knownUrl;audio.load();}}catch{}}
  function deezer(term){return new Promise((resolve,reject)=>{const cb=`idealMusic${Date.now()}${Math.random().toString(36).slice(2)}`,script=document.createElement('script'),timer=setTimeout(()=>{delete window[cb];script.remove();reject(new Error('Deezer 搜索超时'));},15000);window[cb]=d=>{clearTimeout(timer);delete window[cb];script.remove();resolve(d);};script.onerror=()=>{clearTimeout(timer);delete window[cb];script.remove();reject(new Error('Deezer 搜索不可用'));};script.src=`https://api.deezer.com/search?q=${encodeURIComponent(term)}&limit=24&output=jsonp&callback=${cb}`;document.head.appendChild(script);});}
