  async function searchNetease(term){const data=await api(`/search?keywords=${encodeURIComponent(term)}&limit=24&type=1`),songs=data?.result?.songs||data?.songs||[];return songs.map(x=>{const artists=x.ar||x.artists||[],album=x.al||x.album||{};return {id:String(x.id),title:x.name||'',artist:artists.map(a=>a.name).join(' / '),album:album.name||'',cover:album.picUrl||'',source:'netease'};}).filter(x=>x.title);}
  async function searchDeezer(term){const data=await deezer(term);return (data?.data||[]).map(x=>({id:`deezer-${x.id}`,title:x.title||'',artist:x.artist?.name||'',album:x.album?.title||'',cover:x.album?.cover_medium||x.album?.cover||'',playUrl:x.preview||'',source:'deezer'})).filter(x=>x.title);}
