  async function searchQq(term){const data=await qqSearch(term),items=data?.data?.song?.item||[];return items.map(x=>({id:`qq-${x.songmid||x.mid||x.songname}`,title:x.songname||'',artist:(x.singer||[]).map?.(a=>a.name).join(' / ')||'',album:x.albumname||'',cover:'',source:'qq'})).filter(x=>x.title);}
