  async function syncNeteaseProfile(){const data=await api('/user/sync');const profile=data?.profile||{},account=data?.account?.account||data?.account||{},vip=data?.vip?.data||data?.vip||{};const playlists=Array.isArray(data?.playlists)?data.playlists:[];const music=playlists.flatMap(list=>Array.isArray(list.tracks)?list.tracks.map(song=>({id:String(song.id||''),title:song.name||'未命名歌曲',artist:song.ar?.map?.(x=>x.name).join(' / ')||song.artist||'',cover:song.al?.picUrl||song.picUrl||''})):[]).filter(song=>song.id);const vipType=profile.vipType??account.vipType??vip.vipType??vip.type??0;const normalized={userId:String(data?.userId||profile.userId||account.id||''),nickname:profile.nickname||account.nickname||'网易云用户',avatarUrl:profile.avatarUrl||account.avatarUrl||'',signature:profile.signature||profile.description||'',level:profile.level||profile.levelInfo?.level||'',vip:Boolean(profile.isVip||profile.vip||account.isVip||vip.isVip||Number(vipType)>0),vipLabel:profile.vipLabel||vip.label||(Number(vipType)>0?'VIP':'普通用户'),music,playlists:playlists.map(list=>({id:String(list.id||''),name:list.name||'未命名歌单',cover:list.coverImgUrl||list.cover||'',trackCount:Number(list.trackCount||list.size||list.tracks?.length||0),tracks:(list.tracks||[]).map(song=>({id:String(song.id||''),title:song.name||'未命名歌曲',artist:song.ar?.map?.(x=>x.name).join(' / ')||song.artist||'',cover:song.al?.picUrl||song.picUrl||''}))}))};saveNeteaseProfile(normalized);render();return normalized;}
  async function neteaseLogin(){
    if(loginLoading)return;
    const token=++loginPollToken;
    loginLoading=true;loginQr='';loginStatus='';render();
    try{
      const keyData=await api('/auth/qr/key');
      if(token!==loginPollToken)return;
      const key=keyData?.data?.unikey||keyData?.unikey;
      if(!key)throw new Error('无法获取登录二维码');
      const qrSessionToken=keyData?.data?.qrSessionToken||keyData?.qrSessionToken;
      if(!qrSessionToken)throw new Error('音乐接口没有建立扫码会话，请稍后重试');
      const qr=await api(`/auth/qr/create?key=${encodeURIComponent(key)}&qrSessionToken=${encodeURIComponent(qrSessionToken)}`);
      if(token!==loginPollToken)return;
      if(!(qr?.data?.qrimg||qr?.qrimg))throw new Error('无法生成登录二维码');
      const qrQuery=`key=${encodeURIComponent(key)}&qrSessionToken=${encodeURIComponent(qrSessionToken)}`;
      loginQr=qr?.data?.qrimg||qr?.qrimg||'';
      loginStatus='请使用网易云音乐 App 扫码登录';render();
      let failures=0;
      const check=async()=>{
        if(token!==loginPollToken||!app.classList.contains('is-open'))return;
        try{
          const status=await api(`/auth/qr/check?${qrQuery}&timestamp=${Date.now()}`);
          if(token!==loginPollToken)return;
          failures=0;
          const code=Number(status?.data?.code??status?.code);
          if(status?.sessionToken||status?.data?.sessionToken){
            localStorage.setItem(sessionKey,status.sessionToken||status.data.sessionToken);
            loginQr='';loginLoading=false;loginStatus='';
            try{await syncNeteaseProfile();lyricRequested.clear();lyricLoading.clear();loadLyrics(current());window.alert('网易云音乐登录成功，个人页面已同步。');}
            catch(error){window.alert(`登录成功，但个人页面同步失败：${error.message}`);}
            render();return;
          }
          if(code===-462){loginQr='';loginLoading=false;render();window.alert('网易云拒绝了当前登录服务（-462）。请确认音乐登录 Worker 已部署最新版本后，再重新生成二维码；手机端不能使用电脑的 127.0.0.1 服务。');return;}
          if(code===803){loginQr='';loginLoading=false;render();window.alert(status?.error||'手机已授权，但音乐接口没有返回登录凭证，请重新扫码。');return;}
          if(code===800){loginQr='';loginLoading=false;render();window.alert('二维码已过期，请重新登录。');return;}
          const upstreamMessage=String(status?.data?.message||status?.message||status?.error||'').trim();
          if(code!==801&&code!==802){
            loginLoading=false;
            loginStatus=upstreamMessage||`网易云登录失败（${code}）`;
            render();
            window.alert(loginStatus);
            return;
          }
          const nextStatus=code===802?'手机已扫码，请在网易云音乐 App 中确认授权':'等待手机扫码…';
          if(loginStatus!==nextStatus){loginStatus=nextStatus;render();}
          setTimeout(check,2000);
        }catch(error){
          if(token!==loginPollToken||error?.name==='AbortError')return;
          failures+=1;
          if(failures<4){loginStatus=`连接中断，正在重试（${failures}/3）…`;render();setTimeout(check,2000);return;}
          loginQr='';loginLoading=false;render();window.alert(`二维码状态检查失败：${error.message}`);
        }
      };
      check();
    }catch(error){if(token!==loginPollToken||error?.name==='AbortError')return;loginQr='';loginLoading=false;render();const message=/failed to fetch/i.test(String(error?.message||''))?(/^https?:\/\/(?:localhost|127\.0\.0\.1)/i.test(neteaseAuthApiBase)?'请先在项目根目录运行：node music-auth-server.mjs':`请确认 ${neteaseAuthApiBase} 已部署，并允许当前网页域名访问。`):error.message||'登录服务不可用，请检查登录后端配置。';window.alert(`网易云登录失败：${message}`);}
  }
  async function logoutNetease(){try{await api('/auth/logout',{method:'POST'});}catch{}localStorage.removeItem(sessionKey);saveNeteaseProfile(null);loginQr='';loginLoading=false;render();window.alert('已彻底退出网易云音乐账号。');}
  async function importFiles(files){const entries=Array.from(files||[]).filter(f=>f.type.startsWith('audio/')||/\.(mp3|m4a|aac|wav|flac|ogg)$/i.test(f.name));if(!entries.length)return;for(const file of entries){const title=file.name.replace(/\.[^.]+$/,'');const track={id:uid(),title,artist:'本地音乐',source:'file'};await putFile(track.id,file);library().push(track);}save();page='my';render();}
