  async function loadPublicCatalog(){if(publicLoading||publicTracks.some(song=>song.id.startsWith('archive-chopin-')))return;publicLoading=true;try{const response=await fetch('https://archive.org/metadata/musopen-chopin');if(!response.ok)throw new Error('catalog');const data=await response.json();const files=(data.files||[]).filter(file=>/\.mp3$/i.test(file.name||'')).slice(0,80);if(files.length)publicTracks=files.map(file=>{const url=`https://archive.org/download/musopen-chopin/${encodeURIComponent(file.name)}`;return {id:`archive-chopin-${file.name}`,title:String(file.name).replace(/\.mp3$/i,''),artist:'Frédéric Chopin · Musopen',source:'url',url,playUrl:url,isPublic:true};});}finally{publicLoading=false;}}
