  async function loadLyrics(song){const lyricId=song?.source==='netease'?song.id:song?.musicId;if(!song||!lyricId||song.lyric&&song.lyrics?.length||lyricRequested.has(lyricId))return;lyricRequested.add(lyricId);lyricLoading.add(lyricId);if(current()?.id===song.id&&app.classList.contains('is-open'))render();try{const data=await api(`/lyric/${encodeURIComponent(lyricId)}`),lyric=typeof data?.lrc?.lyric==='string'?data.lrc.lyric:(typeof data?.lyric==='string'?data.lyric:''),yrc=typeof data?.yrc?.lyric==='string'?data.yrc.lyric:(typeof data?.yrc==='string'?data.yrc:'');const lyrics=lyricLines({lyric,yrc});if((lyric||yrc)&&current()?.id===song.id){state.current[state.profileId]={...current(),lyric:lyric||yrc,yrc,lyrics};save();}}catch{lyricRequested.delete(lyricId);}finally{lyricLoading.delete(lyricId);if(current()?.id===song.id&&app.classList.contains('is-open')){render();updateProgress();}}}
