  function decorateNeteasePlaylists(){if(page!=='my'||!neteaseProfile?.playlists?.length)return;const card=app.querySelector('.music-netease-account');if(!card||card.querySelector('.music-netease-playlists'))return;const panel=document.createElement('div');panel.className='music-netease-playlists';const selected=neteaseProfile.playlists.find(list=>list.id===selectedPlaylistId);panel.innerHTML=selected?`<div class="music-netease-playlists-title"><button class="music-playlist-back" data-music-playlist-back type="button">‹ 返回歌单</button><span>${esc(selected.name)} · ${selected.tracks?.length||0} 首</span></div><div class="music-playlist-tracks">${selected.tracks?.length?selected.tracks.map(song=>`<article class="music-song"><div class="music-cover">${cover(song)}</div><div><b>${esc(song.title)}</b><small>${esc(song.artist||'网易云音乐')}</small></div><button data-music-playlist-song="${esc(song.id)}" type="button">${svg('play')}</button></article>`).join(''):'<div class="music-empty">这个歌单暂时没有可播放歌曲。</div>'}</div>`:`<div class="music-netease-playlists-title">我的歌单 <span>${neteaseProfile.playlists.length} 个</span></div>${neteaseProfile.playlists.slice(0,20).map(list=>`<button class="music-netease-playlist" data-music-playlist="${esc(list.id)}" type="button"><div>${list.cover?`<img src="${esc(list.cover)}" alt="">`:svg('music')}</div><span><b>${esc(list.name)}</b><small>${list.trackCount?`${list.trackCount} 首歌曲`:'网易云歌单'}</small></span><em>›</em></button>`).join('')}`;const actions=card.querySelector('.music-netease-account-actions');card.insertBefore(panel,actions);}
