  function decoratePlaybackControls(){const controls=app.querySelector('.music-player-controls');if(!controls)return;const primary=controls.querySelector('.music-play-control');if(primary){const primaryState=playing?'pause':'play';if(primary.dataset.musicPrimaryState!==primaryState){primary.dataset.musicPrimaryState=primaryState;primary.innerHTML=primarySvg(primaryState);}primary.style.setProperty('display','grid','important');primary.style.setProperty('background','#18181a','important');primary.style.setProperty('color','#fff','important');primary.style.setProperty('border-radius','50%','important');primary.style.setProperty('opacity','1','important');primary.style.setProperty('visibility','visible','important');}if(controls.querySelector('[data-music-mode]'))return;const button=document.createElement('button');button.dataset.musicMode='';button.type='button';button.title=modeLabel();button.setAttribute('aria-label',modeLabel());button.innerHTML=svg(modeIcon());controls.insertBefore(button,controls.querySelector('[data-music-prev]'));}
